import{_ as t,o as a,c as r,a4 as i}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"ADR-0011 — Model Registry en YAML et capacités typées","description":"Extrait de docs/adr/0011-model-registry-yaml-et-capacites-typees.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0011 — Model Registry en YAML et capacités typées","description":"Extrait de docs/adr/0011-model-registry-yaml-et-capacites-typees.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0011-model-registry-yaml-et-capacites-typees.md","filePath":"developpeurs/adr/0011-model-registry-yaml-et-capacites-typees.md"}'),s={name:"developpeurs/adr/0011-model-registry-yaml-et-capacites-typees.md"};function n(o,e,c,d,l,u){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0011--model-registry-en-yaml-et-capacités-typées" tabindex="-1">ADR-0011 — Model Registry en YAML et capacités typées <a class="header-anchor" href="#adr-0011--model-registry-en-yaml-et-capacités-typées" aria-label="Permalink to &quot;ADR-0011 — Model Registry en YAML et capacités typées {#adr-0011--model-registry-en-yaml-et-capacités-typées}&quot;">​</a></h1><p><strong>Date :</strong> 20 août 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1 §14.1-14.3, §14.8 ; Epic E8 (AI Socle, jalon M8a)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Depuis l&#39;Epic E2, cinq registres déclaratifs du Core sont écrits <strong>en Python</strong> : <code>BlockRegistry</code> (E2), <code>EntrySettingRegistry</code> (E4), <code>ServiceRegistry</code> (E5), <code>RoleRegistry</code> (E6), <code>PluginCatalogue</code> (E7). Chacun décrit des choses que du code exécute — un bloc a un rendu, un rôle ouvre des permissions vérifiées par des fonctions — et les tenir dans le même langage que leur exécution est cohérent.</p><p>L&#39;Epic E8 doit décrire autre chose : ce que le CMS <em>peut solliciter</em> chez un fournisseur d&#39;IA (nom de modèle, capacité, fenêtre de contexte, dimension d&#39;embedding, protocole). Deux questions se posaient donc ensemble :</p><ol><li>Ce catalogue suit-il le patron Python des cinq registres précédents ?</li><li>Un modèle est-il décrit par une interface unique (<code>AIProvider.call(payload) -&gt; payload</code>) ou par des capacités séparées ?</li></ol><p>Le CDC répond aux deux (« entrées déclaratives, capacités typées <code>LLM · Embedding · Vision · OCR · STT</code> »), mais l&#39;écart avec le patron établi du dépôt méritait d&#39;être acté plutôt que constaté dans une docstring.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>1. Le Model Registry est déclaratif en YAML</strong> (<code>apps/api/app/ai/catalogue/*.yaml</code>), chargé au démarrage et validé par Pydantic aussi strictement que du code — un fichier mal formé est refusé en bloc, jamais chargé à moitié. Un exploitant complète le catalogue par <code>AI_MODEL_REGISTRY_DIR</code>, sans modifier les fichiers livrés et sans déploiement de code. Les clés sont uniques toutes sources confondues : un catalogue n&#39;en redéfinit pas un autre.</p><p><strong>2. Une entrée = une capacité</strong>, en union discriminée par <code>capability</code> (même patron qu&#39;<code>E1 FieldDefinition</code>, <code>E3 FilterSpec</code>, <code>E4 LifecycleRule</code>). Un modèle multimodal se déclare deux fois, avec le même <code>runtime_name</code>.</p><p><strong>3. Cinq ports typés</strong> (<code>app/ai/ports.py</code>), un par capacité, avec leurs paires requête/résultat. Un adaptateur implémente les ports qu&#39;il sert et <strong>aucun autre</strong>.</p><p><strong>4. Le catalogue ne décide jamais de la souveraineté.</strong> Il porte au mieux un <code>hosting_hint</code> indicatif ; le drapeau qui décide, <code>ai_models.data_leaves_infrastructure</code>, est déclaré par l&#39;administrateur en base, daté et attribué.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Registre Python, comme les cinq précédents</strong></td><td>Écartée : ce catalogue change sans que le CMS change (un fournisseur renomme un modèle, une collectivité en héberge un autre chez elle). Exiger un déploiement de code pour ces mouvements-là met l&#39;exploitation sous la dépendance du développement pour des faits qui ne relèvent pas du développement.</td></tr><tr><td><strong>Catalogue stocké en base, éditable depuis l&#39;admin</strong></td><td>Écartée pour cet Epic : le catalogue est une propriété de la distribution, identique pour toutes les organisations — le mettre en base en ferait une donnée par installation à migrer et à sauvegarder, et dupliquerait ce que le code livre déjà. Ce qui est propre à une organisation (fournisseur activé, modèle enregistré, politique) est, lui, bien en base.</td></tr><tr><td><strong>Interface unique <code>AIProvider</code></strong></td><td>Écartée : une méthode <code>call(payload: dict) -&gt; dict</code> place la vérification de forme au moment de l&#39;appel, c&#39;est-à-dire chez le fournisseur, après la sortie des données. Avec un port par capacité, demander une génération de texte à un modèle d&#39;embedding est une résolution qui échoue <strong>avant</strong> tout appel.</td></tr><tr><td><strong>Déduire la sortie de données du fournisseur ou de l&#39;URL</strong></td><td>Écartée : un point d&#39;accès « custom » sur le réseau interne peut relayer vers un tiers, et rien dans une requête HTTP ne permet de l&#39;exclure. Une inférence donnerait une fausse assurance à un administrateur qui, lui, sait.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Ajouter ou corriger un modèle est une écriture de fichier de configuration, versionnable et transmissible à un intégrateur — aucune clé d&#39;API n&#39;y figure (le catalogue nomme la variable d&#39;environnement, jamais le secret).</li><li>Les erreurs de routage (mauvaise capacité, adaptateur incomplet) se produisent avant tout appel réseau, et sont journalisées comme des refus et non comme des pannes.</li><li>Une dépendance de plus (<code>pyyaml</code>), et une seule.</li></ul><p><strong>Négatives</strong></p><ul><li>Deux formats déclaratifs coexistent désormais dans le Core (Python pour cinq registres, YAML pour le catalogue de modèles). L&#39;écart est justifié par la nature de l&#39;objet décrit, mais il devra être expliqué à chaque nouvel arrivant — d&#39;où cette ADR.</li><li>Un catalogue modifiable à chaud est un catalogue qu&#39;un exploitant peut casser. Le refus en bloc et la validation Pydantic limitent le risque au démarrage, pas en cours de service.</li><li>Le vocabulaire des capacités existe en deux jeux : celui qu&#39;un plugin déclare (E7) et celui des modèles (E8). La traduction est faite en un seul endroit (<code>app/ai/capabilities.py</code>) et un test de recette vérifie mécaniquement qu&#39;aucune capacité déclarable n&#39;est sans traduction.</li></ul>',19)])])}const g=t(s,[["render",n]]);export{m as __pageData,g as default};
